def common_in_nested_lists(nested_list):
    if not nested_list or any(len(sub) == 0 for sub in nested_list):
        return set()

    # Start with the first sublist as the initial candidate set
    result = set(nested_list[0])

    # Intersect with each subsequent sublist
    for i in range(1, len(nested_list)):
        result &= set(nested_list[i])

    return result

# Example usage and assertion:
nested = [[12, 18, 23, 25, 45], [7, 12, 18, 24, 28], [1, 5, 8, 12, 15, 16, 18]]
assert common_in_nested_lists(nested) == set([18, 12])

print(common_in_nested_lists(nested))  # Output: {18, 12} (order may vary in sets)

